#!/usr/bin/env python3
"""
将Markdown格式的TEE技术PPT转换为HTML演示文稿
"""

import re
import os
from datetime import datetime

def read_markdown_file(filepath):
    """读取Markdown文件"""
    with open(filepath, 'r', encoding='utf-8') as f:
        return f.read()

def parse_markdown_slides(markdown_content):
    """解析Markdown内容为幻灯片"""
    # 按"---"分隔符分割幻灯片
    slides = []
    current_slide = []
    lines = markdown_content.split('\n')

    for line in lines:
        if line.strip() == '---':
            if current_slide:
                slides.append('\n'.join(current_slide))
                current_slide = []
        else:
            current_slide.append(line)

    if current_slide:
        slides.append('\n'.join(current_slide))

    return slides

def extract_slide_title(slide_content):
    """提取幻灯片标题"""
    # 查找一级或二级标题
    lines = slide_content.split('\n')
    for line in lines:
        if line.startswith('# '):
            return line[2:].strip()
        elif line.startswith('## '):
            return line[3:].strip()
    return "Untitled Slide"

def convert_markdown_to_html(slide_content):
    """将Markdown内容转换为HTML"""
    html_lines = []
    lines = slide_content.split('\n')
    in_code_block = False
    code_lang = ""
    code_content = []

    for line in lines:
        # 处理代码块开始
        if line.strip().startswith('```'):
            if not in_code_block:
                in_code_block = True
                # 提取语言
                lang_match = re.match(r'^```(\w*)', line.strip())
                code_lang = lang_match.group(1) if lang_match else ""
            else:
                # 代码块结束
                in_code_block = False
                code_html = f'<pre><code class="language-{code_lang}">\n' + '\n'.join(code_content) + '\n</code></pre>'
                html_lines.append(code_html)
                code_content = []
            continue

        if in_code_block:
            code_content.append(html_escape(line))
            continue

        # 处理标题
        if line.startswith('# '):
            html_lines.append(f'<h1>{line[2:].strip()}</h1>')
        elif line.startswith('## '):
            html_lines.append(f'<h2>{line[3:].strip()}</h2>')
        elif line.startswith('### '):
            html_lines.append(f'<h3>{line[4:].strip()}</h3>')
        elif line.startswith('#### '):
            html_lines.append(f'<h4>{line[5:].strip()}</h4>')

        # 处理列表
        elif line.strip().startswith('- '):
            # 简单列表处理
            content = line.strip()[2:].strip()
            html_lines.append(f'<li>{content}</li>')

        # 处理表格（简化处理）
        elif '|' in line and not line.startswith('|--'):
            if '|' in line and '---' not in line:
                cells = [cell.strip() for cell in line.split('|') if cell.strip()]
                if cells:
                    html_lines.append('<tr>' + ''.join([f'<td>{cell}</td>' for cell in cells]) + '</tr>')

        # 处理普通段落
        elif line.strip() and not line.startswith('|--'):
            html_lines.append(f'<p>{line.strip()}</p>')

    return '\n'.join(html_lines)

def html_escape(text):
    """HTML转义"""
    return (text.replace('&', '&amp;')
                .replace('<', '&lt;')
                .replace('>', '&gt;')
                .replace('"', '&quot;')
                .replace("'", '&#39;'))

def generate_html_presentation(slides, output_path):
    """生成完整的HTML演示文稿"""
    css_style = """
    <style>
        :root {
            --primary-color: #2563eb;
            --secondary-color: #1e40af;
            --accent-color: #3b82f6;
            --text-color: #1f2937;
            --bg-color: #ffffff;
            --code-bg: #f8fafc;
            --border-color: #e5e7eb;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            line-height: 1.6;
            color: var(--text-color);
            background: var(--bg-color);
            overflow-x: hidden;
        }

        .presentation-container {
            display: flex;
            height: 100vh;
        }

        .slides-container {
            flex: 1;
            overflow-y: auto;
            padding: 2rem;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        }

        .slide {
            background: white;
            border-radius: 16px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.1);
