    javascript = """
    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const slides = document.querySelectorAll('.slide');
            const tocLinks = document.querySelectorAll('.toc-link');
            const prevBtn = document.getElementById('prev-slide');
            const nextBtn = document.getElementById('next-slide');

            let currentSlide = 0;

            // 更新活动状态
            function updateActiveSlide(index) {
                // 移除所有活动状态
                slides.forEach(slide => slide.classList.remove('active'));
                tocLinks.forEach(link => link.classList.remove('active'));

                // 添加当前活动状态
                if (slides[index]) {
                    slides[index].classList.add('active');
                    slides[index].scrollIntoView({ behavior: 'smooth', block: 'start' });
                }

                if (tocLinks[index]) {
                    tocLinks[index].classList.add('active');
                }

                currentSlide = index;
            }

            // 导航按钮事件
            if (prevBtn) {
                prevBtn.addEventListener('click', () => {
                    if (currentSlide > 0) {
                        updateActiveSlide(currentSlide - 1);
                    }
                });
            }

            if (nextBtn) {
                nextBtn.addEventListener('click', () => {
                    if (currentSlide < slides.length - 1) {
                        updateActiveSlide(currentSlide + 1);
                    }
                });
            }

            // 目录链接事件
            tocLinks.forEach((link, index) => {
                link.addEventListener('click', (e) => {
                    e.preventDefault();
                    updateActiveSlide(index);
                });
            });

            // 键盘导航
            document.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
                    if (currentSlide > 0) {
                        updateActiveSlide(currentSlide - 1);
                    }
                } else if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') {
                    if (currentSlide < slides.length - 1) {
                        updateActiveSlide(currentSlide + 1);
                    }
                } else if (e.key === 'Home') {
                    updateActiveSlide(0);
                } else if (e.key === 'End') {
                    updateActiveSlide(slides.length - 1);
                }
            });

            // 初始化
            updateActiveSlide(0);

            // 添加打印功能
            const printBtn = document.createElement('button');
            printBtn.innerHTML = '🖨️';
            printBtn.className = 'nav-btn';
            printBtn.title = '打印演示文稿';
            printBtn.style.cssText = 'position: fixed; bottom: 2rem; right: 2rem; z-index: 1000;';
            printBtn.onclick = () => window.print();
            document.body.appendChild(printBtn);
        });
    </script>
    """

    toc_html = '<div class="toc-header">📚 目录</div><ul class="toc-list">'
    for i, slide in enumerate(slides):
        title = extract_slide_title(slide)
        if title:
            toc_html += f'<li class="toc-item"><a href="#slide-{i+1}" class="toc-link" data-slide="{i}">{i+1}. {title}</a></li>'
    toc_html += '</ul>'

    slides_html = ''
    for i, slide_content in enumerate(slides):
        slide_html = convert_markdown_to_html(slide_content)
        title = extract_slide_title(slide_content)

        slides_html += f'''
        <div class="slide" id="slide-{i+1}">
            <div class="slide-header">
                <h1>{title}</h1>
            </div>
            <div class="slide-content">
                {slide_html}
            </div>
            <div class="slide-footer">TEE核心技术深度解析</div>
            <div class="slide-number">第 {i+1} 页 / 共 {len(slides)} 页</div>
        </div>
        '''

    current_date = datetime.now().strftime('%Y年%m月%d日')

    html_content = f'''<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>TEE核心技术深度解析 - 技术PPT</title>
    {css_style}
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/themes/prism-tomorrow.min.css">
    <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/prism.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-c.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-python.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-bash.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-javascript.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-rust.min.js"></script>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
</head>
<body>
    <div class="presentation-container">
        <div class="toc-sidebar">
            <div class="toc-header">
                <i class="fas fa-book"></i> 演示文稿目录
            </div>
            {toc_html}
            <div style="margin-top: 2rem; padding: 1rem; background: #0f172a; border-radius: 8px;">
                <p style="font-size: 0.85rem; color: #94a3b8; margin-bottom: 0.5rem;">
                    <i class="fas fa-info-circle"></i> 导航提示：
                </p>
                <ul style="font-size: 0.8rem; color: #cbd5e1; list-style: none; padding-left: 0;">
                    <li style="margin: 0.3rem 0;"><i class="fas fa-arrow-left"></i> 上一页</li>
                    <li style="margin: 0.3rem 0;"><i class="fas fa-arrow-right"></i> 下一页</li>
                    <li style="margin: 0.3rem 0;"><i class="fas fa-home"></i> 回到首页</li>
                    <li style="margin: 0.3rem 0;"><i class="fas fa-print"></i> 打印文档</li>
                </ul>
            </div>
            <div style="margin-top: auto; padding-top: 2rem; border-top: 1px solid #475569; font-size: 0.8rem; color: #94a3b8;">
                <p><i class="fas fa-calendar"></i> 生成日期: {current_date}</p>
                <p><i class="fas fa-user"></i> 技术顾问: 军师小夜</p>
                <p><i class="fas fa-microchip"></i> 技术领域: TEE/机密计算</p>
            </div>
        </div>

        <div class="slides-container">
            {slides_html}
        </div>

        <div class="slide-navigation">
            <button class="nav-btn" id="prev-slide" title="上一页">
                <i class="fas fa-arrow-up"></i>
            </button>
            <button class="nav-btn" id="next-slide" title="下一页">
                <i class="fas fa-arrow-down"></i>
            </button>
        </div>
    </div>

    {javascript}
</body>
</html>'''

    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(html_content)

    print(f"HTML演示文稿已生成: {output_path}")
    print(f"总页数: {len(slides)}")
    return output_path

def main():
    input_file = "TEE_Technical_Core.md"
    output_file = "TEE_Technical_Presentation.html"

    print("开始转换Markdown到HTML演示文稿...")
    print(f"输入文件: {input_file}")
    print(f"输出文件: {output_file}")

    try:
        # 读取Markdown文件
        markdown_content = read_markdown_file(input_file)
        print(f"读取成功，文件大小: {len(markdown_content)} 字符")

        # 解析幻灯片
        slides = parse_markdown_slides(markdown_content)
        print(f"解析成功，共 {len(slides)} 页幻灯片")

        # 生成HTML演示文稿
        output_path = generate_html_presentation(slides, output_file)
        print(f"转换完成！")

        # 显示幻灯片标题
        print("\n幻灯片标题:")
        for i, slide in enumerate(slides):
            title = extract_slide_title(slide)
            if title:
                print(f"  第{i+1:2d}页: {title}")

    except Exception as e:
        print(f"转换过程中出错: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    main()

