    lines = slide_content.split('\n')
    for line in lines:
        if line.startswith('# '):
            return line[2:].strip()
        elif line.startswith('## '):
            return line[3:].strip()
    return "Untitled Slide"

def convert_markdown_to_html(slide_content):
    """将Markdown内容转换为HTML"""
    html_lines = []
    lines = slide_content.split('\n')
    in_code_block = False
    code_lang = ""
