            printBtn.style.cssText = 'position: fixed; bottom: 2rem; right: 2rem; z-index: 1000;';
            printBtn.onclick = () => window.print();
            document.body.appendChild(printBtn);
        });
    </script>
    """

    toc_html = '<div class="toc-header">📚 目录</div><ul class="toc-list">'
